<?php
require_once dirname(__DIR__).'/repositories/userPDO.php';
function startSecureSession(): void {if(session_status()===PHP_SESSION_ACTIVE)return;$https=!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off';if(!empty($_SERVER['HTTP_X_FORWARDED_PROTO'])&&$_SERVER['HTTP_X_FORWARDED_PROTO']==='https')$https=true;session_set_cookie_params(['lifetime'=>0,'path'=>'/','secure'=>$https,'httponly'=>true,'samesite'=>'Lax']);session_start();}
function csrfToken(): string {startSecureSession();if(empty($_SESSION['csrf_token']))$_SESSION['csrf_token']=bin2hex(random_bytes(32));return $_SESSION['csrf_token'];}
function csrfField(): string {return '<input type="hidden" name="csrf_token" value="'.htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8').'">';}
function verifyCsrfToken(array $input): void {startSecureSession();if(empty($input['csrf_token'])||!hash_equals($_SESSION['csrf_token']??'',(string)$input['csrf_token'])){http_response_code(403);exit('Invalid CSRF token.');}}
function requirePost(): void {if(($_SERVER['REQUEST_METHOD']??'GET')!=='POST'){http_response_code(405);exit('POST required');}}
function requireLogin(PDO $pdo): array {startSecureSession();if(empty($_SESSION['user_id'])){header('Location: login.php');exit;}if(time()-($_SESSION['last_activity']??0)>1200){logoutSession();header('Location: login.php?expired=1');exit;}$u=findUserById($pdo,(int)$_SESSION['user_id']);if(!$u||$u['status']!=='Active'){logoutSession();header('Location: login.php?inactive=1');exit;}$_SESSION['last_activity']=time();$_SESSION['role']=$u['role'];$_SESSION['display_name']=$u['full_name'];return $u;}
function requireRole(array $u,array $roles): void {if(!in_array($u['role'],$roles,true)){http_response_code(403);exit('You are not authorized to perform this action.');}}
function loginSession(array $u): void {startSecureSession();session_regenerate_id(true);$_SESSION['user_id']=(int)$u['user_id'];$_SESSION['role']=$u['role'];$_SESSION['display_name']=$u['full_name'];$_SESSION['last_activity']=time();csrfToken();}
function logoutSession(): void {startSecureSession();$_SESSION = [];if (ini_get('session.use_cookies')) {$params = session_get_cookie_params();setcookie(session_name(), '', ['expires' => time() - 42000,'path' => $params['path'],'domain' => $params['domain'],'secure' => $params['secure'],'httponly' => $params['httponly'],'samesite' => $params['samesite'] ?? 'Lax']);}session_destroy();}
function currentStudentId(PDO $pdo,array $u): int {$s=$pdo->prepare('SELECT student_id FROM students WHERE user_id=?');$s->execute([(int)$u['user_id']]);$id=$s->fetchColumn();if(!$id){http_response_code(403);exit('No student profile is linked to this account.');}return (int)$id;}
function requireRequestAccess(PDO $pdo,array $u,int $requestId): array {requireRole($u,['Student','Administrator']);if($u['role']==='Administrator'){$r=findRequest($pdo,$requestId);}else{$r=findOwnedRequest($pdo,$requestId,(int)$u['user_id']);}if(!$r){http_response_code(404);exit('Request not found.');}return $r;}
